#include <stdio.h>

int main(void) {
    long long N, M;
    if (scanf("%lld %lld", &N, &M) != 2) return 0;

    if (N == 0) {
        printf("S\n");
    } else if (1 + 5 * (N - 1) <= M) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
```

